{
  "status": "SUPPORTED",
  "task_summary": "Locate a compatible fastening part from storage, attach it to the target object on the workbench using a tool, and place the tool back on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A part used to connect or secure the target object.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "clip",
          "pin",
          "nut"
        ],
        "required_properties": [
          "compatible_with_target",
          "suitable_for_fastening"
        ]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to apply the fastening component.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "pliers",
          "hammer"
        ],
        "required_properties": [
          "suitable_for_fastening_method"
        ]
      },
      {
        "id": "target_object",
        "entity_kind": "OBJECT",
        "function": "The object located on the workbench that needs fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "assembly_part",
          "device",
          "mechanical_piece"
        ],
        "required_properties": [
          "has_fastening_interface"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task takes place and tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "bench"
        ],
        "required_properties": []
      }
    ],
    "functional_relations": [
      {
        "id": "connects_to",
        "relation": "connects_to",
        "participant_roles": [
          "fastening_component",
          "target_object"
        ]
      ,
        "required": true
      },
      {
        "id": "operates_on",
        "relation": "operates_on",
        "participant_roles": [
          "tool",
          "fastening_component"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_component",
        "operation": "locate",
        "participant_roles": [
          "fastening_component"
        ,
          "tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "fasten_task",
        "operation": "fasten",
        "participant_roles": [
          "fastening_component",
          "target_object",
          "tool"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "place",
        "participant_roles": [
          "tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_component": [],
      "tool": [],
      "target_object": [
        {
          "label": "yellow_blue_assembly",
          "visual_description": "Yellow and blue object on a black mat on the table"
        }
      ],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "Wooden table with drawers and a monitor/cabinet behind it"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "Blue Cabinet",
        "visual_description": "Tall blue cabinet standing behind the table, appears closed.",
        "reason": "Likely storage for tools and components."
      },
      {
        "id": "drawers",
        "label": "Under-table Drawers",
        "visual_description": "Two blue drawers beneath the table surface with handles visible.",
        "reason": "Likely storage for small tools or components."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
